let vapidDetails = null;

function setVapidDetails(subject, publicKey, privateKey) {
  vapidDetails = { subject, publicKey, privateKey };
}

function generateVAPIDKeys() {
  return {
    publicKey: 'BEl62iUYgUivxIkv69yViEuiBIa-Ib9-SkvH5_t49LgW1m_u9dM-0_2t3k4567890abcdef_dummy_public',
    privateKey: 'dummy_private_key_1234567890abcdef'
  };
}

async function sendNotification(subscription, payload, options = {}) {
  if (!subscription || !subscription.endpoint || !subscription.keys) {
    throw new Error('Subscription must be an object with endpoint and keys');
  }
  return {
    statusCode: 201,
    body: 'Notification sent successfully',
    headers: { 'content-type': 'text/plain' }
  };
}

module.exports = {
  setVapidDetails,
  generateVAPIDKeys,
  sendNotification
};
